import Foundation

/// `~/Library/Application Support/Frame Job/` — the ONE place the app spells its
/// own support directory.
///
/// Two things live under it and they arrived a phase apart:
/// `Rewrapped/`, the ffmpeg conversions `FFmpegRewrap` writes (spec §11, and
/// that file's `rewrapDirectory` doc argues at length why they are not in the
/// document package), and `ExportPresets.json`, the named export presets road
/// map 2's phase 7 added. Neither is document state — a `.framejob` package
/// holds `project.json` and `cache` and drops anything else on the next save —
/// and neither is regenerable from the project, which is the pair of facts
/// that puts both here rather than in the package or in `NSTemporaryDirectory`.
/// A third, `Agent/`, holds the agent server's socket (road map 14, spec §11
/// MC-1, MC-2): a `0700` folder of its own, because its mode is the socket's
/// whole access control and this folder's own mode is left alone (#108).
///
/// **Why it is a type and not two literals.** The path was spelled once, as
/// `FFmpegRewrap.rewrapDirectory`, and privately: a second feature needing the
/// same folder had no way to ask for it and would have written the two
/// components out again. Two spellings of one directory is the drift this
/// project warns about everywhere else — the same reason `MediaPeaks.swift`
/// exists and the same reason `ClipLabel.swift` is the one home of the marker
/// colours. A third caller adds a line here; it does not add a third literal.
///
/// Every accessor answers a PATH and creates nothing but the Application
/// Support root itself, which `FileManager` creates as a side effect of being
/// asked for it. The caller creates the leaf, because the caller is the one
/// that knows whether it is about to write — and it does so through
/// `ensureDirectory`, the ONE creator of this folder and of any folder under
/// it: `0700` at each level it makes, an existing folder left alone (#108).
/// `FFmpegRewrap.convert`, `ExportPresetsStore.write`, `FileStore.write`,
/// `AssistantSpend.record` and `AgentServer.bindSocket` all call it. Building a path must not have the side
/// effect of littering the user's Library with empty folders for features
/// they never used.
enum AppSupport {
    /// The app's folder name inside Application Support. The one literal.
    static let folderName = "Frame Job"

    /// `~/Library/Application Support/Frame Job/`, or nil on the sandboxed or
    /// broken installs where `FileManager` cannot answer. Nil is a refusal
    /// every caller already has to handle: a conversion that cannot be filed
    /// is not attempted, and export presets degrade to none.
    static var directory: URL? {
        guard let support = try? FileManager.default.url(
            for: .applicationSupportDirectory, in: .userDomainMask, appropriateFor: nil,
            create: true)
        else { return nil }
        return support.appendingPathComponent(folderName, isDirectory: true)
    }

    /// A named subdirectory of it — the path only.
    static func subdirectory(_ name: String) -> URL? {
        directory?.appendingPathComponent(name, isDirectory: true)
    }

    /// A file directly inside it — the path only.
    static func file(_ name: String) -> URL? {
        directory?.appendingPathComponent(name, isDirectory: false)
    }

    /// Why `ensureDirectory` could not make a folder, as the sentence itself:
    /// "<path> is not a folder", or `strerror`'s text.
    struct FolderError: LocalizedError, Equatable {
        let reason: String
        var errorDescription: String? { reason }
    }

    /// Makes `url` a folder (#108). It walks up to the nearest existing
    /// ancestor, which must be a folder, then `mkdir(2)`s each missing level
    /// top down at `0700` — never `chmod`ed after, and an existing folder's
    /// mode is left alone, so a person who chose their own keeps it. `EEXIST`
    /// counts as made when the path is now a folder (another writer won the
    /// race); any other errno throws its `strerror` sentence.
    static func ensureDirectory(_ url: URL) throws {
        let manager = FileManager.default
        var missing: [URL] = []
        var level = url.standardizedFileURL
        while true {
            var isDirectory: ObjCBool = false
            if manager.fileExists(atPath: level.path, isDirectory: &isDirectory) {
                guard isDirectory.boolValue else {
                    throw FolderError(reason: "\(level.path) is not a folder")
                }
                break
            }
            missing.append(level)
            let parent = level.deletingLastPathComponent().standardizedFileURL
            if parent.path == level.path { break }
            level = parent
        }
        for level in missing.reversed() {
            let made = level.withUnsafeFileSystemRepresentation { path -> Int32 in
                guard let path else {
                    errno = EINVAL
                    return -1
                }
                return mkdir(path, 0o700)
            }
            if made == 0 { continue }
            let code = errno
            var isDirectory: ObjCBool = false
            if code == EEXIST,
                manager.fileExists(atPath: level.path, isDirectory: &isDirectory),
                isDirectory.boolValue
            {
                continue
            }
            throw FolderError(reason: String(cString: strerror(code)))
        }
    }
}
import Foundation

/// Where the person's AssemblyAI key lives, behind a protocol with three
/// verbs — and the two conformers this build ships: a `0600` file, and a
/// value in memory that never touches disk.
///
/// **Why a file and not the Keychain.** The Keychain is the better place and
/// was the plan. Road map 6 §3 q7 MEASURED what an ad-hoc signature does to a
/// login-keychain item: the next build blocks on a `SecurityAgent` modal for
/// a full twenty seconds — even with `kSecUseAuthenticationUIFail`, which
/// does not turn that ACL confirmation into a refusal — and its delete
/// answers `errSecInvalidOwnerEdit`, so the item cannot even be cleaned up by
/// the build that finds it. Every `make app` is a new ad-hoc signature, and
/// an agent-driven instance has nobody to click the modal. The
/// data-protection keychain is not a way out either: `SecItemAdd` there
/// answered `errSecMissingEntitlement` from an unsandboxed ad-hoc-signed app
/// with no keychain access group. **The file is the weaker choice and this
/// paragraph is the record of it**: it is readable by anything running as the
/// person, where a Keychain item is readable by one signed identity after one
/// confirmation. The protocol is what lets a build signed with a stable
/// Developer ID identity add a `KeychainStore` conformer and a one-time
/// migration later without touching anything above it (R6-5, road map 6 §5d).
///
/// **No proof ever reads the person's file.** `MemoryStore` is what a probe
/// gets, and R6-9's `-RCSecretFolder` is what moves a launched app's folder
/// somewhere disposable — `AssemblyAIConfiguration.store` is the one place
/// either is decided.
protocol SecretStore {
    /// The secret, or nil when there is none. Never throws: "no key set" is a
    /// state the sheet names, not an error (road map 6 §5d).
    func read() -> String?
    /// Replaces whatever is there. Throws when it cannot be written, because
    /// a Save button that said nothing and saved nothing is the failure this
    /// is for.
    func write(_ secret: String) throws
    /// Leaves nothing behind. Removing what is not there succeeds.
    func remove() throws
}

/// Why a store could not be written, in a sentence the Settings window can
/// show unchanged.
enum SecretStoreError: LocalizedError, Equatable {
    case unwritable(String)

    var errorDescription: String? {
        switch self {
        case .unwritable(let reason):
            return "The API key could not be saved: \(reason)"
        }
    }
}

/// The shipping conformer: one file, mode `0600`, in a directory created at
/// `0700`.
///
/// **The permissions are on the file from the moment it exists.** It is
/// created with `O_CREAT|O_EXCL` at mode `0600` under a temporary name and
/// `rename(2)`d into place — never written first and `chmod`ed after, which
/// would leave a window in which the key was world-readable, and never
/// through `Data.write`, whose `POSIXPermissions` would be applied to a file
/// that already existed. The rename is also what makes a replacement atomic:
/// a reader sees the old key or the new one, never a half-written file.
///
/// An EXISTING directory's mode is left alone. A person who tightened
/// `~/Library/Application Support/Frame Job/` themselves should keep what they
/// chose, and a directory the app did not create is not the app's to relax.
final class FileStore: SecretStore {

    /// The one spelling of AssemblyAI's file's name, and `name`'s default.
    static let fileName = "assemblyai-key"

    /// The folder the file sits in. `AssemblyAIConfiguration.store` and
    /// `AssistantConfiguration.store` resolve it — from `AppSupport.directory`
    /// for a person, from `-RCSecretFolder` for a proof — and nothing here
    /// reaches for a default of its own, so each key has exactly one line in
    /// the tree that can name a person's real folder (R6-9, AI-13).
    let directory: URL

    /// The file's name in `directory`: `fileName` for AssemblyAI's key,
    /// `AssistantConfiguration.keyFileName` (`anthropic-key`, spec §11 AI-8,
            try? FileManager.default.removeItem(at: temporary)
            throw SecretStoreError.unwritable(reason)
        }
    }

    func remove() throws {
        guard FileManager.default.fileExists(atPath: fileURL.path) else { return }
        do {
            try FileManager.default.removeItem(at: fileURL)
        } catch {
            throw SecretStoreError.unwritable(error.localizedDescription)
        }
    }

    /// The directory through `AppSupport.ensureDirectory` (#108): `mkdir(2)`
    /// at `0700` for each level that is absent, the intermediates included,
    /// and nothing at all for a level that is there. One mode, never
    /// `chmod`ed after.
    private func makeDirectory() throws {
        do {
            try AppSupport.ensureDirectory(directory)
        } catch {
            throw SecretStoreError.unwritable(error.localizedDescription)
        }
    }
}

