/// **The key is never a tool argument, a launch argument or an answer**
/// (AI-8, R6-12): `credential` hands it to `AssistantSession.open`, which
/// writes it into the helper's `configure` on stdin and nowhere else. No tool
/// reads or writes the model (AI-11); it is a person's setting.
enum AssistantConfiguration {

    /// The store's file, beside AssemblyAI's `assemblyai-key`.
    static let keyFileName = "anthropic-key"

    /// The environment override, read only when the store has nothing
    /// (R6-5, R6-9 (d)).
    static let environmentKey = "ANTHROPIC_API_KEY"

    /// The helper's `api_base` (AI-13): the stand-in server's address in a
    /// proof. `protocol.ts` calls it "an environment variable of its own".
    static let baseURLVariable = "RC_ASSISTANT_BASE_URL"

    /// The persisted model, Settings' Assistant pane from A2.
    static let modelKey = "FrameJobAssistantModel"

    /// AI-11's default.
    static let defaultModel = "claude-opus-5-5"

    /// The helper's `ChatSettings` (`agent/src/protocol.ts`): the person's
    /// chat settings from Settings' Assistant pane (AI-20). A dev build's
    /// `-RCDevAssistantAutoCompact <tokens>` replaces the threshold, even
    /// with compaction off, for a proof (AI-18).
    static func settingsJSON(defaults: UserDefaults = .standard) -> [String: Any] {
        var json = AssistantChatSettings.load(from: defaults).helperJSON
        #if FRAMEJOB_DEV_TOOLS
        if let tokens = devAutoCompactTokens(defaults: defaults) {
            json["auto_compact_tokens"] = tokens
        }
        #endif
        return json
    }

    /// Why the base-URL override cannot be used, in the sentence the session
    /// refuses with.
    enum ConfigurationError: LocalizedError, Equatable {
        case malformedBase(String)

    /// The store-folder override (R6-9). A PATH, never a key — `ps` shows
    /// every launch argument to every user on the machine, which is the same
    /// reason R6-5 keeps the credential out of `transcribe`'s arguments.
    static let secretFolderArgument = "RCSecretFolder"

    /// The persisted region, the Settings window's popup.
    static let regionKey = "FrameJobAssemblyAIRegion"

    /// The environment override, read only when the store has nothing
    /// (R6-5, R6-9 (d)).
    static let environmentKey = "RC_ASSEMBLYAI_KEY"

    /// AssemblyAI's two data regions (road map 6 §2). A transcript made in
    /// one is not visible in the other, which is why this is a setting and
    /// not a fallback.
    enum Region: String, CaseIterable {
        case us
        case eu

        var base: URL {
            switch self {
            case .us: return Region.url("https://api.assemblyai.com")
            case .eu: return Region.url("https://api.eu.assemblyai.com")
            }
        }

        /// `URL(string:)` is optional because its input is usually somebody
        /// else's; these two are literals on the lines above. A parse that
        /// failed would be a typo there, and the fallback reaches no host at
        /// all — every request against it refuses, which is the safe
        return url
    }

    /// The `SecretStore` this process may use, and R6-9's whole decision in
    /// one function.
    ///
    /// With `-RCSecretFolder` set, a `FileStore` on that folder: a proof's
    /// own disposable directory. With no `-RCSecretFolder` but
    /// `-RCAssemblyAIEndpoint` set, an EMPTY `MemoryStore`: the app has been
    /// pointed at something that is not AssemblyAI, so the person's stored
    /// key is not opened at all and `RC_ASSEMBLYAI_KEY` is the only
    /// credential such a run can have. With neither, the person's own file
    /// under `AppSupport.directory` — the ONE line in this feature that names
    /// it. A machine with no Application Support folder answers an empty
    /// `MemoryStore` too, which reads as "no key is set".
    static func store(defaults: UserDefaults = .standard) -> any SecretStore {
        if let folder = argument(secretFolderArgument, defaults: defaults) {
            return FileStore(
                directory: URL(
                    fileURLWithPath: (folder as NSString).expandingTildeInPath,
                    isDirectory: true))
        }
        if argument(endpointArgument, defaults: defaults) != nil { return MemoryStore() }
        guard let directory = AppSupport.directory else { return MemoryStore() }
        return FileStore(directory: directory)
    }

    /// The credential: the store first, the environment second (R6-5, and
    /// R6-9 (d) amends the wording of that order and not the order). An empty
    /// environment variable is no credential, for `FileStore.read`'s reason.
    static func credential(
        defaults: UserDefaults = .standard,
        environment: [String: String] = ProcessInfo.processInfo.environment
    ) -> URL? {
        if let path = AssemblyAIConfiguration.argument(folderArgument, defaults: defaults) {
            return URL(
                fileURLWithPath: (path as NSString).expandingTildeInPath, isDirectory: true)
        }
        if let base = environment[AssistantConfiguration.baseURLVariable], !base.isEmpty {
            return nil
        }
        return AppSupport.directory
    }

    /// `configure`'s `price_cache` and `price_feed` (`agent/src/protocol.ts`):
    /// the cache in the spend folder, when there is one and, with the
    /// base-URL override set, only beside `-RCPriceFeed`.
    static func configureFields(
        defaults: UserDefaults = .standard,
        environment: [String: String] = ProcessInfo.processInfo.environment
    ) -> [String: Any] {
        var fields: [String: Any] = [:]
        let feed = AssemblyAIConfiguration.argument(feedArgument, defaults: defaults)
        if let feed { fields["price_feed"] = feed }
        guard let folder = folder(defaults: defaults, environment: environment) else {
            return fields
        }
        let overridden = !(environment[AssistantConfiguration.baseURLVariable] ?? "").isEmpty
        if overridden && feed == nil { return fields }
        fields["price_cache"] = folder.appendingPathComponent(priceCacheName).path
        return fields
    }
/// "saving a preset" means and it has no `NSPopUpButton` in it.
///
/// **Every failure degrades to "no presets".** A missing file, a directory
/// where the file should be, a truncated write, a JSON object where an array
/// belongs, a record from a newer build: all of them answer an empty store, and
/// none of them throws, alerts or interrupts. The list is a convenience over a
/// dialog that works perfectly without it, so the worst outcome a corrupt file
/// may cause is that the popup is empty — never a lost export, never a crash,
/// and never a modal about a preferences file in the middle of somebody's work.
struct ExportPresetsStore: Equatable {
    /// The file inside `AppSupport.directory`.
    static let fileName = "ExportPresets.json"

    /// In the order they were first saved. Not sorted: a person's own order is
