    /// conversion is cached by name, so leaving it there would hand the same
    /// broken result back for ever; throwing it away makes the next attempt
    /// a real attempt. Only the file that was probed is thrown away: one
    /// another import has since put at the name is left (spec §11 #227). The
    /// error its caller reports is the ORIGINAL one, because the file the
    /// user chose is the one they are being told about.
    private static func probeConversion(_ rewrapped: URL, of url: URL) -> MediaDescriptor? {
        let probed = FFmpegRewrap.fileNumber(of: rewrapped)
        guard var descriptor = try? waitForProbe(rewrapped) else {
            FFmpegRewrap.discard(rewrapped, ifStill: probed)
            return nil
        }
        descriptor.original = MediaOriginal(of: url)
        return descriptor
    }

    /// The built-in copy of `source` probed, with `source` recorded as its
    /// `original` (spec §11 #228-O). A copy the one-frame decode
    /// refuses is thrown away and refused in the source's name (#216's
    /// backstop); any other failure throws the copy away too, so the next
    /// import copies again rather than reuse a movie that will not open.
    private static func probeCopy(_ copy: URL, of source: URL) throws -> MediaDescriptor {
        do {
            var descriptor = try waitForProbe(copy)
            descriptor.original = MediaOriginal(of: source)
            return descriptor
        } catch ImportError.undecodable(_, let sentence) {
            FFmpegRewrap.discard(copy)
            let copyName = copy.lastPathComponent
            let named = sentence.hasPrefix(copyName)
                ? source.lastPathComponent + sentence.dropFirst(copyName.count) : sentence
            throw ImportError.undecodable(source, sentence: named)
        } catch {
            FFmpegRewrap.discard(copy)
            throw ContainerRewrapError.failed(source, reason: "the copied movie could not be read")
        }
    }

